(function () {
    const root = $.GetContextPanel();

    const goldLabel = root.FindChildTraverse("GoldValue");
    const woodLabel = root.FindChildTraverse("WoodValue");
    const killLabel = root.FindChildTraverse("KillValue");

    function FormatUnit(value, unit) {
        let text = value.toFixed(2);
        text = text.replace(/\.?0+$/, "");
        return text + unit;
    }

    function FormatCompact(value) {
        if (!value || value === 0) return "";

        const abs = Math.abs(value);
        const sign = value < 0 ? "-" : "";

        if (abs >= 1000000) {
            return sign + FormatUnit(abs / 1000000, "m");
        }

        if (abs >= 1000) {
            return sign + FormatUnit(abs / 1000, "k");
        }

        return sign + Math.floor(abs).toString();
    }

    function Update() {
        const localID = Players.GetLocalPlayer();

        // Wood & Kill 通过 CustomNetTables
        const t = CustomNetTables.GetTableValue("player_resource_ext", "" + localID) || {};

        goldLabel.text = FormatCompact(t.gold) || 0;
        woodLabel.text = FormatCompact(t.wood) || 0;
        killLabel.text = FormatCompact(t.kill) || 0;

        $.Schedule(0.2, Update);
    }

    Update();
})();

